def find_rectangles(grid, target_color):
    result = []
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_color:
                # Start from here, check if this is top-left corner of rectangle
                # We need to find the largest rectangle that has its top-left at (r,c)
                # and is filled with target_color
                max_rect = (r, c, 0, 0)
                best_rect = max_rect

                for height in range(1, h - r + 1):
                    for width in range(1, w - c + 1):
                        # Check if this region is filled with target_color
                        is_filled = True
                        for rr in range(r, r + height):
                            for cc in range(c, c + width):
                                if grid[rr][cc] != target_color:
                                    is_filled = False
                                    break
                            if not is_filled:
                                break

                        if is_filled:
                            if height * width > best_rect[2] * best_rect[3]:
                                best_rect = (r, c, height, width)

                result.append(best_rect)
                # Skip ahead to be more efficient
                # Move to next pixel that might be a top-left corner
                break  
    return result

