    rect_end_col = rect_c + rect_w  # 10 for Demo 1

    output = [[0 for _ in range(w)] for _ in range(h)]

    # Fill expanded rectangle: rows 0 to rect_end_row-1, cols 0 to rect_end_col-1
    if rect_end_col > w:
        rect_end_col = w
    for r in range(rect_end_row):
        for c in range(rect_end_col):
            output[r][c] = 2

    # Strip columns pattern
    # For even rect_w: [0, 2, 4, rect_w-3]
    # For odd rect_w: [0, 2, rect_w-2]
    if rect_w % 2 == 0:
        strip_offsets = [0, 2, 4, rect_w - 3]
    else:
        strip_offsets = [0, 2, rect_w - 2]

    strip_cols = [rect_c + off for off in strip_offsets]

    # For each strip column, put 2s in the bottom rows (from rect_end_row to h-1)
    for c in strip_cols:
        for r in range(rect_end_row, h):
            output[r][c] = 2

    # Now handle special pixels
    # For each special pixel in input:
    # If r > rect_end_row, output position is (r-1, c)
    # Otherwise output position is (r, c)
