def final_transform(grid):
    """
    Rectangle fill transformation:
    - Find rect of 2s
    - Fill region from row 0 to rect_r + rect_h - 1
    - Rows with special pixels → bar-fill (rect columns)
    - Rows without → full-fill (all columns)
    - Strip region fills computed columns
    """
    h, w = len(grid), len(grid[0])
    rect_r, rect_c = h, w
    max_r, max_c = -1, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                if r < rect_r or (r == rect_r and c < rect_c):
                    rect_r, rect_c = r, c
                if r > max_r or (r == max_r and c > max_c):
                    max_r, max_c = r, c

    if max_r == -1:
        return [row[:] for row in grid]

    rect_h = max_r - rect_r + 1
    rect_w = max_c - rect_c + 1
    fill_end = rect_r + rect_h

    output = [[0 for _ in range(w)] for _ in range(h)]

    # Fill region
    for r in range(fill_end):
        has_special = any(grid[r][c] != 0 and grid[r][c] != 2 for c in range(w))
        if has_special:
            for c in range(rect_c, rect_c + rect_w):
                output[r][c] = 2
        else:
            for c in range(w):
                output[r][c] = 2

    # Strip region
    if rect_w % 2 == 0:
        strip_offsets = [0, 2, 4, rect_w - 3]
    else:
        strip_offsets = [0, 2, rect_w - 2]
    strip_cols = [rect_c + off for off in strip_offsets]
    for r in range(fill_end, h):
        for c in strip_cols:
            output[r][c] = 2

    return output

